    state.mixing = true; $('mixBtn').disabled = true; $('mixBtn').textContent = `MIXING TO ${incomingName}`; const start = +$('crossfader').value, began = performance.now(); await new Promise(resolve => { const tick = now => { const amount = Math.min(1, (now - began) / 2200), eased = amount * amount * (3 - 2 * amount); $('crossfader').value = start + (target - start) * eased; updateCrossfader(); amount < 1 ? requestAnimationFrame(tick) : resolve(); }; requestAnimationFrame(tick); }); state.active = incomingName; state.mixing = false; $('mixBtn').disabled = false; updateCrossfader(); updateNowPlaying(); if (!decks[outgoingName].audio.paused) decks[outgoingName].audio.pause(); rememberPlayed(incoming.track.id); updateDeck(outgoingName); updateDeck(incomingName);
